use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut lc: Vec<int> = []
    let mut rc: Vec<int> = []
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut x: int = 0
        if parts.len() > 1 {
            x = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            if root == -1 {
                keys.push(x)
                lc.push(-1)
                rc.push(-1)
                root = 0
                println("ok")
            } else {
                let mut cur = root
                let mut done = false
                while !done {
                    let k = keys[cur as usize]
                    if x == k {
                        println("dup")
                        done = true
                    } else if x < k {
                        let n = lc[cur as usize]
                        if n == -1 {
                            let id = keys.len() as int
                            keys.push(x)
                            lc.push(-1)
                            rc.push(-1)
                            lc[cur as usize] = id
                            println("ok")
                            done = true
                        } else {
                            cur = n
                        }
                    } else {
                        let n = rc[cur as usize]
                        if n == -1 {
                            let id = keys.len() as int
                            keys.push(x)
                            lc.push(-1)
                            rc.push(-1)
                            rc[cur as usize] = id
                            println("ok")
                            done = true
                        } else {
                            cur = n
                        }
                    }
                }
            }
        } else if cmd == "contains" {
            let mut cur = root
            let mut found = false
            while cur != -1 && !found {
                let k = keys[cur as usize]
                if x == k {
                    found = true
                } else if x < k {
                    cur = lc[cur as usize]
                } else {
                    cur = rc[cur as usize]
                }
            }
            if found {
                println("yes")
            } else {
                println("no")
            }
        } else if cmd == "delete" {
            let mut cur = root
            let mut p: int = -1
            let mut found = false
            while cur != -1 && !found {
                let k = keys[cur as usize]
                if x == k {
                    found = true
                } else {
                    p = cur
                    if x < k {
                        cur = lc[cur as usize]
                    } else {
                        cur = rc[cur as usize]
                    }
                }
            }
            if !found {
                println("missing")
            } else {
                let l = lc[cur as usize]
                let r = rc[cur as usize]
                if l != -1 && r != -1 {
                    let mut s = r
                    let mut sp = cur
                    while lc[s as usize] != -1 {
                        sp = s
                        s = lc[s as usize]
                    }
                    keys[cur as usize] = keys[s as usize]
                    if sp == cur {
                        rc[sp as usize] = rc[s as usize]
                    } else {
                        lc[sp as usize] = rc[s as usize]
                    }
                } else {
                    let mut child = l
                    if l == -1 {
                        child = r
                    }
                    if p == -1 {
                        root = child
                    } else if lc[p as usize] == cur {
                        lc[p as usize] = child
                    } else {
                        rc[p as usize] = child
                    }
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            if root == -1 {
                println("<empty>")
            } else {
                let mut stack: Vec<int> = []
                let mut out: Vec<string> = []
                let mut cur = root
                while cur != -1 || stack.len() > 0 {
                    while cur != -1 {
                        stack.push(cur)
                        cur = lc[cur as usize]
                    }
                    let top = stack.pop().unwrap_or(-1)
                    out.push("${keys[top as usize]}")
                    cur = rc[top as usize]
                }
                println(out.join(" "))
            }
        } else if cmd == "height" {
            let mut best = 0
            if root != -1 {
                let mut ns: Vec<int> = [root]
                let mut ds: Vec<int> = [1]
                while ns.len() > 0 {
                    let n = ns.pop().unwrap_or(-1)
                    let d = ds.pop().unwrap_or(0)
                    if d > best {
                        best = d
                    }
                    if lc[n as usize] != -1 {
                        ns.push(lc[n as usize])
                        ds.push(d + 1)
                    }
                    if rc[n as usize] != -1 {
                        ns.push(rc[n as usize])
                        ds.push(d + 1)
                    }
                }
            }
            println("${best}")
        } else if cmd == "min" || cmd == "max" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur = root
                if cmd == "min" {
                    while lc[cur as usize] != -1 {
                        cur = lc[cur as usize]
                    }
                } else {
                    while rc[cur as usize] != -1 {
                        cur = rc[cur as usize]
                    }
                }
                println("${keys[cur as usize]}")
            }
        }
    }
}

